LineContribType* calculate_line_contributions(unsigned int line_size, unsigned int src_size, double scale_d, const interpolation_method* pFilter) {
    if (line_size == 0 || src_size == 0 || scale_d <= 0.0 || pFilter == NULL) {
        return NULL;
    }

    int filter_width = (int)(scale_d + 0.5);  // Assume midpoint rounding
    LineContribType* contribs = (LineContribType*)malloc(line_size * sizeof(LineContribType));
    if (contribs == NULL) {
        return NULL;
    }

    for (unsigned int i = 0; i < line_size; ++i) {
        double x = (double)i / scale_d;
        int left = (int)(x - filter_width / 2.0);
        int right = (int)(x + filter_width / 2.0);

        double total_weight = 0.0;
        int contrib_count = 0;

        for (int j = left; j <= right; ++j) {
            if (j < 0 || j >= (int)src_size) {
                continue;
            }

            double weight = pFilter->calculate(j - x);
            contribs[i].contrib[contrib_count].src_idx = j;
            contribs[i].contrib[contrib_count].weight = weight;
            total_weight += weight;
            ++contrib_count;
        }

        if (total_weight <= 0.0) {
            for (unsigned int k = 0; k < i; ++k) {
                free(contribs[k].contrib);
            }
            free(contribs);
            return NULL;
        }

        for (int k = 0; k < contrib_count; ++k) {
            contribs[i].contrib[k].weight /= total_weight;
        }

        contribs[i].count = contrib_count;
    }

    return contribs;
}

LineContribType* calculate_contributions(unsigned int line_size, unsigned int src_size, double scale_d, const interpolation_method* pFilter) {
    if (!pFilter || line_size == 0 || src_size == 0 || scale_d <= 0.0) {
        return NULL;
    }

    int filter_width = (int)(scale_d + 0.5);
    if (filter_width <= 0) {
        return NULL;
    }

    LineContribType* contribs = (LineContribType*)malloc(line_size * sizeof(LineContribType));
    if (!contribs) {
        return NULL;
    }

    double total_weight = 0.0;

    for (unsigned int i = 0; i < line_size; ++i) {
        int left = (int)((double)i / scale_d) - filter_width;
        int right = (int)((double)i / scale_d) + filter_width;

        if (left < 0) {
            left = 0;
        }

        if (right > (int)src_size) {
            right = src_size;
        }

        contribs[i].start = left;
        contribs[i].end = right;

        double weight = 0.0;
        for (int j = left; j < right; ++j) {
            double dx = (double)(i / scale_d) - j;
            double w = pFilter(dx, scale_d);
            weight += w;
        }

        contribs[i].weight = weight;
        total_weight += weight;
    }

    if (total_weight <= 0.0) {
        free(contribs);
        return NULL;
    }

    for (unsigned int i = 0; i < line_size; ++i) {
        contribs[i].weight /= total_weight;
    }

    return contribs;
}

