typedef struct {
    int* left;
    int* right;
    double* weight;
} LineContribType;

typedef double (*interpolation_method)(int, double);

LineContribType* calculate_contributions(unsigned int line_size, unsigned int src_size, double scale_d, interpolation_method pFilter) {
    int filter_width = (int)(0.5 / scale_d) * 2 + 1;
    LineContribType* contrib = (LineContribType*)malloc(sizeof(LineContribType));
    if (!contrib) return NULL;

    contrib->left = (int*)malloc(line_size * sizeof(int));
    contrib->right = (int*)malloc(line_size * sizeof(int));
    contrib->weight = (double*)malloc(line_size * sizeof(double));

    if (!contrib->left || !contrib->right || !contrib->weight) {
        free(contrib->left);
        free(contrib->right);
        free(contrib->weight);
        free(contrib);
        return NULL;
    }

    for (unsigned int i = 0; i < line_size; i++) {
        double x = (double)i / scale_d;
        contrib->left[i] = (int)x - (filter_width - 1) / 2;
        contrib->right[i] = contrib->left[i] + filter_width - 1;

        double total_weight = 0.0;
        for (int j = contrib->left[i]; j <= contrib->right[i]; j++) {
            if (j >= 0 && j < (int)src_size) {
                double dx = (double)(i * src_size - j) / scale_d;
                total_weight += pFilter(j, dx);
            }
        }

        if (total_weight <= 0.0) {
            for (unsigned int k = 0; k < line_size; k++) {
                free(contrib->left);
                free(contrib->right);
                free(contrib->weight);
            }
            free(contrib->left);
            free(contrib->right);
            free(contrib->weight);
            free(contrib);
            return NULL;
        }

        contrib->weight[i] = total_weight;
    }

    return contrib;
}

