    int filter_width = (int)(2.0 * scale_d + 1.0);

    // Allocate memory for contributions
    LineContribType* contributions = (LineContribType*)malloc(line_size * sizeof(LineContribType));
    if (!contributions) {
        return NULL; // Memory allocation failed
    }

    for (unsigned int i = 0; i < line_size; i++) {
        // Calculate left and right edge points based on filter width
        int left = (int)(i / scale_d) - filter_width / 2;
        int right = left + filter_width;

        // Compute the total weight of contributions
        double total_weight = 0.0;
        for (int j = left; j < right; j++) {
            if (j < 0 || j >= (int)src_size) {
                continue; // Skip out of bounds pixels
            }
            double weight = pFilter->calculate_weight((double)(i) / scale_d - j);
            contributions[i].weight[j] = weight;
            total_weight += weight;
        }

        // Normalize the weights
        if (total_weight != 0.0) {
            for (int j = left; j < right; j++) {
